function adrenal(){const r=context('adrenal','Suprarrenal direita — córtex e medula','Corte de uma glândula com contorno triangular arredondado. Bandas corticais ampliadas e medula central; sem zona celular em escala real.');const p=[[-.43,-.27],[-.32,.05],[-.12,.39],[.12,.37],[.35,.1],[.45,-.2],[.15,-.29],[-.15,-.28]],scaled=s=>p.map(([x,y])=>[x*s,y*s]);for(const[key,label,a,b,color,fn,tissue]of[['capsule','Cápsula suprarrenal',1,.93,C.white,'Revestir a glândula.','connective'],['zona_glomerulosa','Zona glomerulosa',.92,.78,C.gold,'Produzir mineralocorticoides, incluindo aldosterona.','organ'],['zona_fasciculata','Zona fasciculada',.77,.54,C.pink,'Produzir glicocorticoides, incluindo cortisol.','organ'],['zona_reticularis','Zona reticular',.53,.37,C.brown,'Produzir andrógenos adrenais.','organ']])r.part(r.shape(scaled(a),.055,color,-.025,[scaled(b)]),key,label,fn,tissue);r.part(r.shape(scaled(.35),.042,C.purple,.003),'medulla','Medula suprarrenal','Liberar catecolaminas pelas células cromafins.','neural');r.part(bundle(r.tube([[-.48,.11,.08],[-.19,.14,.08],[0,.0,.08]],.012,C.artery),r.tube([[0,0,.09],[.17,-.25,.09],[.24,-.4,.09]],.018,C.blue)),'vessels','Vasos suprarrenais','Conduzir sangue e hormônios da glândula.','vascular');return r.finish()}

