function testis(){const r=context('testis','Testículo — lóbulos e via de saída','Corte longitudinal com túbulos simbólicos e ductos adjacentes. O número de lóbulos foi reduzido e os ductos foram ampliados.');r.part(r.ellipse([-.05,0,-.08],[.31,.44],C.white,.10,[.285,.405]),'tunica_albuginea','Túnica albugínea','Revestir o testículo e formar septos internos.','connective');const lobules=new THREE.Group();for(let i=0;i<7;i++){const a=-1.1+i*.34;lobules.add(r.shape([[.19,0],[-.05+.27*Math.cos(Math.PI+a),.39*Math.sin(Math.PI+a)],[-.05+.27*Math.cos(Math.PI+a+.28),.39*Math.sin(Math.PI+a+.28)]],.055,i%2?C.pink:C.gold,-.04))}r.part(lobules,'lobules','Lóbulos testiculares','Organizar túbulos seminíferos entre septos.','organ');const tubules=new THREE.Group();for(let j=0;j<5;j++){const pts=[];for(let i=0;i<24;i++)pts.push([-.2+.013*i+.018*Math.sin(i*2),.28-j*.135+.025*Math.sin(i*.8),.035]);tubules.add(r.tube(pts,.008,C.cream,55))}r.part(tubules,'seminiferous_tubules','Túbulos seminíferos','Sustentar a formação de espermatozoides.','organ');r.part(r.tube([[.17,.29,.055],[.20,0,.055],[.17,-.23,.055]],.025,C.gold),'rete_testis','Rede testicular','Reunir o conteúdo vindo dos túbulos.','organ');const ductules=new THREE.Group();for(let i=0;i<4;i++)ductules.add(r.tube([[.16,.12+i*.04,.05],[.27,.27+i*.018,.05],[.31,.26+i*.025,.05]],.008,C.gold));r.part(ductules,'efferent_ductules','Dúctulos eferentes','Conectar rede testicular e epidídimo.','organ');r.part(r.tube([[.23,.38,.02],[.34,.3,.02],[.34,-.1,.02],[.22,-.41,.02]],.041,C.brown,60),'epididymis','Epidídimo adjacente','Favorecer maturação e armazenamento de espermatozoides.','organ');r.part(r.tube([[.23,-.4,.03],[.43,-.28,.03],[.46,.17,.03],[.46,.51,.03]],.023,C.pink),'vas_deferens','Ducto deferente','Transportar espermatozoides por contrações musculares.','muscle');return r.finish()}

function ovary(){const r=context('ovary','Ovário — folículos e região medular','Corte didático com estágios foliculares e corpo lúteo lado a lado para comparação. Não representa a evolução instantânea de um único ciclo.');r.part(r.ellipse([0,0,-.07],[.44,.30],C.pink,.08,[.29,.19]),'cortex','Córtex ovariano','Abrigar a maior parte dos folículos.','organ');r.part(r.ellipse([0,0,-.065],[.29,.19],C.red,.045),'medulla','Medula ovariana','Conduzir vasos e sustentar o órgão.','organ');const primordial=new THREE.Group();for(let i=0;i<7;i++)primordial.add(r.ellipse([-.25+i*.035,.2+Math.sin(i)*.025,.03],[.015,.015],C.cream,.015));r.part(primordial,'primordial_follicles','Folículos primordiais (ampliados)','Manter oócitos no estoque folicular.','organ');r.part(bundle(r.ellipse([-.29,-.09,.045],[.07,.07],C.gold,.04,[.028,.028]),r.ball([-.29,-.09,.04],[.018,.018,.018],C.cream)),'growing_follicle','Folículo em crescimento','Sustentar desenvolvimento do oócito e atividade endócrina.','organ');r.part(bundle(r.ellipse([.29,.045,.04],[.13,.115],C.gold,.04,[.095,.08]),r.ball([.365,.02,.073],[.022,.022,.016],C.cream)),'mature_follicle','Folículo antral maduro','Preparar condições para ovulação e produzir estradiol.','organ');const luteal=r.shape([[-.02,-.19],[.02,-.14],[.08,-.18],[.12,-.23],[.07,-.25],[.02,-.26],[-.02,-.24]],.04,C.gold,.035);r.part(luteal,'corpus_luteum','Corpo lúteo: estágio comparativo','Produzir progesterona após ovulação.','organ');r.part(bundle(r.tube([[-.58,.03,.035],[-.2,.02,.035],[.02,-.03,.035],[.18,.05,.035]],.012,C.artery),r.tube([[-.56,-.035,.01],[-.2,-.05,.01],[.04,-.01,.01]],.014,C.blue)),'ovarian_vessels','Vasos ovarianos','Permitir nutrição e distribuição de hormônios.','vascular');return r.finish()}


function prostate(){const r=context('prostate','Próstata — corte ao redor da uretra','Esquema frontal de parênquima e uretra atravessando o órgão. Não mostra zonas clínicas completas nem alterações patológicas.');const outer=[[-.4,.17],[-.28,.36],[.03,.33],[.28,.3],[.4,.14],[.31,-.2],[.04,-.32],[-.28,-.2]],inner=outer.map(([x,y])=>[x*.91,y*.9]);r.part(r.shape(outer,.09,C.white,-.05,[inner]),'capsule','Cápsula prostática','Revestir a glândula.','connective');r.part(r.shape(inner,.065,C.pink,-.025,[[[-.045,.35],[.045,.35],[.045,-.34],[-.045,-.34]]]),'glandular_zone','Parênquima glandular','Produzir componentes da secreção prostática.','organ');r.part(r.shell([[0,.49,.065],[0,0,.065],[0,-.46,.065]],.036,.007,C.gold),'prostatic_urethra','Uretra prostática','Conduzir conteúdo através da próstata.','organ');const ducts=new THREE.Group();for(const s of[-1,1])for(let i=0;i<3;i++)ducts.add(r.tube([[s*.28,.18-i*.14,.10],[s*.12,.11-i*.09,.10],[s*.04,.05-i*.07,.10]],.008,C.cream));r.part(ducts,'ducts','Ductos prostáticos','Conduzir secreção glandular à uretra.','organ');r.part(r.shape([[-.29,.21],[0,.31],[.29,.21],[.25,.11],[0,.16],[-.25,.11]],.026,C.red,.048),'fibromuscular_stroma','Estroma fibromuscular (ampliado)','Sustentar a glândula e cooperar na ejeção de secreções.','muscle');return r.finish()}

function skin(){const r=context('skin','Pele — bloco em corte','Camadas de pele com folículo, glândulas, vasos e receptores ampliados. O tamanho relativo dos anexos foi ajustado e não indica densidade real.');
  const layer=(top,bottom,color)=>{const pts=[];for(let i=0;i<=16;i++)pts.push([-.5+i/16,top+.018*Math.sin(i*1.3)]);for(let i=16;i>=0;i--)pts.push([-.5+i/16,bottom+.018*Math.sin(i*1.3)]);return r.shape(pts,.24,color,-.16)};
  r.part(layer(.34,.25,C.brown),'epidermis','Epiderme','Formar barreira epitelial de proteção.','skin');r.part(layer(.24,-.13,C.pink),'dermis','Derme','Sustentar anexos, vasos, nervos e resistência mecânica.','connective');const sub=bundle(layer(-.14,-.34,C.fat));for(let i=0;i<7;i++)sub.add(r.ball([-.4+i*.13,-.26,.085],[.071,.062,.04],C.gold));r.part(sub,'hypodermis','Hipoderme: região subcutânea','Contribuir para reserva, isolamento e ancoragem da pele.','fat');
  const hair=bundle(r.tube([[-.17,-.19,.11],[-.15,.06,.11],[-.10,.38,.11],[-.05,.54,.11]],.024,C.brown),r.tube([[-.17,-.18,.10],[-.15,.04,.10],[-.1,.28,.10]],.042,C.cream));r.part(hair,'hair_follicle','Folículo piloso e pelo','Produzir e abrigar o pelo.','organ');const sebum=new THREE.Group();for(let i=0;i<4;i++)sebum.add(r.ball([-.07+.032*Math.cos(i*1.5),.1+.034*Math.sin(i*1.5),.115],[.038,.028,.022],C.gold));r.part(sebum,'sebaceous_gland','Glândula sebácea','Liberar secreção lipídica associada ao folículo.','organ');const coil=[];for(let i=0;i<=50;i++){const a=i/50*Math.PI*10;coil.push([.23+.042*Math.cos(a),-.09+.018*Math.sin(a),.085+i*.0008])}r.part(bundle(r.tube(coil,.009,C.red,90),r.tube([[.23,-.075,.12],[.21,.13,.12],[.27,.34,.12]],.011,C.red)),'sweat_gland','Glândula sudorípara e ducto','Produzir suor e conduzi-lo à superfície.','organ');r.part(bundle(r.ellipse([.4,-.07,.11],[.045,.07],C.cream,.025),r.tube([[.4,-.07,.11],[.32,-.2,.11],[.12,-.23,.11]],.007,C.gold)),'sensory_receptors','Receptor sensorial: símbolo ampliado','Transduzir estímulos cutâneos.','neural');r.part(bundle(r.tube([[-.46,-.15,.13],[0,-.17,.13],[.46,-.15,.13]],.012,C.artery),r.tube([[-.45,-.2,.14],[0,-.21,.14],[.45,-.2,.14]],.013,C.blue)),'vessels','Vasos dérmicos','Nutrir tecidos e participar de trocas térmicas.','vascular');return r.finish()}

function skeletalMuscle(){const r=context('skeletal-muscle','Músculo esquelético — hierarquia em corte','Músculo, fascículos e fibra destacada em escalas comparativas. As bainhas conjuntivas estão espessadas; não representa a quantidade real de fibras.');const path=[[0,-.44,0],[0,.44,0]];
  r.part(r.taperedTube(path,[.115,.23,.25,.23,.115],C.white,true,.013),'epimysium','Epimísio','Envolver o músculo como órgão.','connective');const fascicles=new THREE.Group(),peri=new THREE.Group(),endo=new THREE.Group();for(const[x,z]of[[-.12,-.04],[0,-.07],[.12,-.04],[-.07,-.15],[.07,-.15]]){fascicles.add(r.rod([x,-.41,z],[x,.41,z],.043,C.red));peri.add(r.shell([[x,-.43,z],[x,.43,z]],.051,.006,C.cream));for(let j=0;j<3;j++)endo.add(r.rod([x+(j-1)*.017,-.40,z+.03],[x+(j-1)*.017,.40,z+.03],.003,C.white))}r.part(fascicles,'fascicles','Fascículos musculares','Agrupar fibras para organização mecânica.','muscle');r.part(peri,'perimysium','Perimísio','Envolver cada fascículo.','connective');r.part(endo,'endomysium','Endomísio: bainhas representadas','Envolver fibras individuais e sustentar trocas.','connective');const fiber=bundle(r.rod([.34,-.25,.02],[.34,.36,.02],.034,C.pink));for(let i=0;i<11;i++)fiber.add(r.ring([.34,-.22+i*.05,.02],.035,.0018,C.brown,'y'));r.part(fiber,'muscle_fiber','Fibra muscular: ampliação separada','Converter ativação em força pela contração.','muscle');r.part(bundle(r.tube([[-.41,.12,.08],[-.19,.06,.08],[.02,.02,.08]],.011,C.gold),r.tube([[-.19,.06,.08],[-.05,-.06,.08]],.009,C.gold)),'motor_nerve','Ramo nervoso motor','Levar sinais para ativação das fibras.','neural');r.part(bundle(r.taperedTube([[0,-.60,0],[0,-.50,0],[0,-.40,0]],[.066,.077,.11],C.cream),r.taperedTube([[0,.40,0],[0,.5,0],[0,.60,0]],[.11,.077,.066],C.cream)),'tendon','Continuidade tendínea','Transmitir força para estruturas de inserção.','connective');r.part(bundle(r.tube([[.17,-.45,.08],[.17,0,.08],[.17,.45,.08]],.010,C.artery),r.tube([[.205,-.45,.08],[.205,0,.08],[.205,.45,.08]],.011,C.blue)),'vessels','Vasos musculares','Fornecer substratos e remover produtos metabólicos.','vascular');return r.finish()}

function bone(){const r=context('bone','Osso longo — córtex e cavidade medular','Osso longo genérico em corte. Trabéculas são uma malha ilustrativa; faixa de crescimento identifica apenas um osso ainda em desenvolvimento.');const outer=[[-.13,.33],[-.27,.47],[-.24,.60],[0,.65],[.24,.60],[.27,.47],[.13,.33],[.11,-.31],[.25,-.46],[.23,-.58],[0,-.63],[-.23,-.58],[-.25,-.46],[-.11,-.31]],inner=[[-.063,.42],[.063,.42],[.066,-.42],[-.066,-.42]];
  r.part(r.shape(outer,.15,C.cream,-.09,[inner]),'cortical_bone','Osso cortical','Oferecer resistência mecânica pela matriz compacta.','bone');const lattice=new THREE.Group();for(const y of[-.5,.5])for(let i=0;i<6;i++){const x=-.17+i*.065;lattice.add(r.rod([x,y-.065,.087],[x+.055,y+.065,.087],.007,C.cream));lattice.add(r.rod([x,y+.065,.087],[x+.055,y-.065,.087],.007,C.cream))}r.part(lattice,'spongy_bone','Osso esponjoso: trabéculas','Distribuir cargas e delimitar espaços medulares.','bone');r.part(r.shape(inner,.03,C.gold,-.086),'marrow','Medula óssea: cavidade representada','Abrigar tecido medular; regiões vermelhas podem realizar hematopoiese.','fat');r.part(r.shape(outer.map(([x,y])=>[x*1.045,y*1.02]),.022,C.white,-.11,[outer]),'periosteum','Periósteo','Revestir e nutrir superfícies não articulares.','connective');r.part(r.shape(inner.map(([x,y])=>[x*1.13,y*1.015]),.01,C.pink,.066,[inner]),'endosteum','Endósteo','Revestir superfícies internas e participar da remodelação.','connective');r.part(r.tube([[.43,.06,.095],[.19,.03,.095],[0,-.03,.095],[0,-.35,.095]],.010,C.artery),'nutrient_artery','Artéria nutrícia','Levar sangue ao interior ósseo.','vascular');r.part(bundle(r.organic([[-.13,.335],[-.04,.35],[.04,.35],[.13,.335],[.12,.317],[.04,.33],[-.04,.33],[-.12,.317]],.03,C.blue,.08),r.organic([[-.12,-.325],[-.04,-.337],[.04,-.337],[.12,-.325],[.12,-.345],[.04,-.357],[-.04,-.357],[-.12,-.345]],.03,C.blue,.08)),'epiphyseal_cartilage','Cartilagem epifisária: osso em crescimento','Permitir crescimento longitudinal antes do fechamento.','cartilage');return r.finish()}

function lymphNode(){const r=context('lymph-node','Linfonodo — córtex, medula e fluxo linfático','Corte no hilo, com vasos aferentes na convexidade e saída eferente. Folículos e seios estão ampliados para seleção.');const p=P.kidney.map(([x,y])=>[x*.94,y*.8]),inner=p.map(([x,y])=>[x*.91,y*.91]);r.part(r.shape(p,.05,C.white,-.06,[inner]),'capsule','Cápsula do linfonodo','Revestir o órgão e emitir trabéculas.','connective');r.part(r.shape(inner,.06,C.purple,-.07),'paracortex','Paracórtex','Conter importante território de linfócitos T.','organ');r.part(r.shape(inner,.026,C.pink,.001,[inner.map(([x,y])=>[x*.68,y*.68])]),'cortex','Córtex superficial','Abrigar folículos e linfócitos B.','organ');const follicles=new THREE.Group();for(const[x,y]of[[-.3,.21],[-.39,.06],[-.33,-.13],[-.15,-.25],[-.09,.26]])follicles.add(r.ellipse([x,y,.04],[.04,.035],C.gold,.025));r.part(follicles,'follicles','Folículos linfoides','Organizar respostas de linfócitos B.','organ');r.part(r.shape([[-.11,.15],[.02,.12],[.08,.0],[.02,-.17],[-.19,-.14],[-.24,-.03]],.025,C.red,.006),'medulla','Medula do linfonodo','Conter cordões e seios medulares.','organ');const sinuses=new THREE.Group();for(let i=0;i<4;i++)sinuses.add(r.tube([[-.3,.2-i*.12,.067],[-.1,.16-i*.1,.067],[.08,-.01,.067]],.009,C.cream));r.part(sinuses,'sinuses','Seios linfáticos','Conduzir linfa pelo parênquima.');const aff=new THREE.Group();for(let i=0;i<3;i++)aff.add(r.tube([[-.66,.3-i*.24,.02],[-.44,.24-i*.20,.02]],.015,C.green));r.part(aff,'afferent_vessels','Vasos linfáticos aferentes','Trazer linfa ao linfonodo.','vascular');r.part(r.tube([[.07,-.01,.02],[.24,-.05,.02],[.46,-.06,.02]],.020,C.green),'efferent_vessel','Vaso linfático eferente','Retirar linfa pelo hilo.','vascular');return r.finish()}

function spleen(){const r=context('spleen','Baço — polpas e vasos','Secção do parênquima com nódulos de polpa branca e região de polpa vermelha. As unidades foram ampliadas e reduzidas em número.');const p=[[-.21,.44],[-.45,.27],[-.48,-.06],[-.26,-.4],[.06,-.41],[.23,-.22],[.13,-.04],[.22,.17],[.13,.34]],inner=p.map(([x,y])=>[x*.93,y*.93]);r.part(r.shape(p,.045,C.white,-.04,[inner]),'capsule','Cápsula esplênica','Revestir o baço e sustentar trabéculas.','connective');r.part(r.shape(inner,.055,C.red,-.055),'red_pulp','Polpa vermelha','Filtrar componentes sanguíneos e remover células envelhecidas.','organ');const trab=new THREE.Group();for(let i=0;i<4;i++)trab.add(r.tube([[-.35,.3-i*.17,.015],[-.16,.24-i*.13,.015],[.01,.1-i*.11,.015]],.018,C.cream));r.part(trab,'trabeculae','Trabéculas esplênicas','Oferecer suporte e trajetos vasculares.','connective');const white=new THREE.Group();for(const[x,y]of[[-.25,.2],[-.26,-.1],[-.06,-.22],[.03,.2]]){white.add(r.ellipse([x,y,.06],[.05,.044],C.purple,.028));white.add(r.rod([x-.05,y,.09],[x+.055,y,.09],.006,C.artery))}r.part(white,'white_pulp','Polpa branca: unidades ampliadas','Organizar respostas imunes a antígenos do sangue.','organ');r.part(r.tube([[.46,.17,.06],[.2,.1,.06],[.02,.1,.06],[-.15,.17,.06]],.019,C.artery),'splenic_artery','Artéria esplênica','Levar sangue ao território esplênico.','vascular');r.part(r.tube([[.40,.0,.02],[.19,-.04,.02],[.0,-.12,.02]],.024,C.blue),'splenic_vein','Veia esplênica','Drenar sangue na direção do sistema porta.','vascular');return r.finish()}

function thymus(){const r=context('thymus','Timo — lóbulos e compartimentos','Órgão bilobado didático, sem representar a involução com a idade. Cada lóbulo mostra córtex periférico e medula interna.');const outer=[[-.06,.42],[-.23,.37],[-.4,.1],[-.38,-.3],[-.19,-.38],[0,-.17],[.19,-.38],[.38,-.3],[.4,.1],[.23,.37],[.06,.42],[0,.21]],inner=outer.map(([x,y])=>[x*.94,y*.94]);r.part(r.shape(outer,.04,C.white,-.07,[inner]),'capsule','Cápsula tímica','Revestir o órgão e organizar septos.','connective');const lob=new THREE.Group(),cortex=new THREE.Group(),med=new THREE.Group();for(const[x,y]of[[-.15,.23],[-.24,.03],[-.22,-.19],[.15,.23],[.24,.03],[.22,-.19]]){lob.add(r.ellipse([x,y,-.035],[.102,.13],C.pink,.04));cortex.add(r.ellipse([x,y,.011],[.094,.12],C.purple,.025,[.047,.068]));med.add(r.ellipse([x,y,.016],[.046,.067],C.cream,.024))}r.part(lob,'lobules','Lóbulos tímicos','Compartimentalizar o parênquima do timo.','organ');r.part(cortex,'cortex','Córtex tímico','Participar do desenvolvimento e seleção de timócitos.','organ');r.part(med,'medulla','Medula tímica','Participar da maturação e tolerância imunológica.','organ');r.part(bundle(r.tube([[-.34,-.39,.065],[-.25,0,.065],[-.13,.29,.065]],.009,C.artery),r.tube([[.34,-.39,.065],[.25,0,.065],[.13,.29,.065]],.009,C.artery)),'vessels','Vasos tímicos','Nutrir o tecido e permitir tráfego celular apropriado.','vascular');return r.finish()}

function trachea(){const r=context('trachea','Traqueia — anéis em C e parede','Número de anéis reduzido; abertura posterior e músculo traqueal destacados. A metade anterior da parede foi removida para mostrar a luz.');const path=[[0,.47,0],[0,-.47,0]];r.part(r.shell(path,.195,.013,C.white),'adventitia','Adventícia traqueal','Fixar e sustentar componentes da parede.','connective');r.part(r.shell(path,.17,.014,C.pink),'mucosa','Mucosa respiratória','Condicionar o ar e participar da depuração mucociliar.','organ');r.part(r.shell(path,.153,.002,C.dark),'lumen','Luz traqueal','Permitir passagem de ar.');const rings=new THREE.Group();for(let i=0;i<8;i++){const o=r.ring([0,-.41+i*.117,0],.194,.017,C.cream,'y',Math.PI*1.5);o.rotation.z=-Math.PI/4;rings.add(o)}r.part(rings,'cartilage_rings','Cartilagens traqueais em C','Manter a via aérea aberta sem fechar rigidamente a face posterior.','cartilage');r.part(r.organic([[-.115,.47],[.115,.47],[.105,-.47],[-.105,-.47]],.026,C.red,-.17),'trachealis_muscle','Músculo traqueal: parede posterior','Ajustar calibre e completar a parede posterior.','muscle');return r.finish()}

