 r.part(r.organic([[-.008,.28],[.034,.28],[.04,.07],[.052,-.10],[.078,-.28],[.03,-.36],[-.05,-.21],[-.066,-.054],[-.012,.08]],.14,C.red,.083),'septum','Septo interventricular','Separar as cavidades ventriculares.','muscle');
 function valve(key,label,x,y,rx,rz,n){const objects=[];const loop=[];for(let i=0;i<=40;i++){const a=i/40*Math.PI*2;loop.push([x+rx*Math.cos(a),y,.05+rz*Math.sin(a)])}objects.push(r.tube(loop,.006,C.cream));for(let i=0;i<n;i++)objects.push(r.leaflet([x,y,.05],rx,rz,i/n*Math.PI*2,(i+1)/n*Math.PI*2,C.cream));r.part(bundle(objects),key,label,'Responder a diferenças de pressão e limitar refluxo.','connective')}
 valve('tricuspid_valve','Valva tricúspide',-.23,.07,.074,.049,3);valve('mitral_valve','Valva mitral',.195,.075,.069,.045,2);valve('pulmonary_valve','Valva pulmonar',-.055,.29,.044,.033,3);valve('aortic_valve','Valva aórtica',.085,.28,.040,.032,3);
 const cords=[];for(const x of[-.215,.215])for(let i=0;i<4;i++)cords.push(r.taperedTube([[x+(i-1.5)*.023,.048,.052],[x+(i-1.5)*.009,-.035,.065],[x,-.098,.035]],[.003,.002,.003],C.cream));r.part(bundle(cords),'chordae_tendineae','Cordas tendíneas','Ligar cúspides atrioventriculares aos músculos papilares.','connective');
