const BUILDERS={heart:heartDetailed,lungs:lungsDetailed,kidney:kidneyDetailed,liver:liverDetailed,stomach:stomachDetailed,'small-intestine':smallIntestine,'large-intestine':largeIntestine,pancreas,gallbladder,esophagus,bladder,brain:brainDetailed,'spinal-cord':spinalCord,eye:eyeDetailed,ear,thyroid,adrenal,pituitary,testis,ovary,uterus:uterusDetailed,prostate,skin,'skeletal-muscle':skeletalMuscle,bone,'lymph-node':lymphNode,spleen,thymus,trachea,penis};
