export const INTERNAL_MODEL_IDS=Object.freeze(Object.keys(BUILDERS));
export function createInternalModel(id){const canonical=ALIASES[id]||id,builder=BUILDERS[canonical];if(!builder)throw new RangeError('Modelo interno inexistente: '+id);return builder()}
